<template>
  <div
    class="my-2 flex w-[470px] flex-col gap-2 rounded-lg bg-surface-elevation-2 p-3 shadow-2xl ring-1 ring-black ring-opacity-5 focus:outline-none"
  >
    <div class="text-base text-ink-gray-5">
      {{ __('Assign To') }}
    </div>

    <Link
      class="form-control"
      value=""
      doctype="User"
      :placeholder="__('John Doe')"
      :filters="{
        name: ['in', eligibleUserNames],
        ignore_user_type: 1,
      }"
      :hide-me="true"
      @change="
        (option) =>
          addValue(option) &&
          ($refs.input.value = '')
      "
    >
      <template #target="{ togglePopover }">
        <div
          class="flex min-h-12 w-full cursor-text flex-wrap items-center gap-1.5 rounded-lg bg-surface-gray-2 p-1.5 pb-5"
          @click.stop="togglePopover"
        >
          <Tooltip
            v-for="assignee in assignees"
            :key="assignee.name"
            :text="assignee.name"
            @click.stop
          >
            <div
              class="flex cursor-pointer items-center rounded-full border border-outline-gray-1 bg-surface-elevation-2 p-0.5 text-sm text-ink-gray-6"
              @click.stop
            >
              <UserAvatar
                :user="assignee.name"
                size="sm"
              />

              <div class="ml-1">
                {{
                  getUser(assignee.name)
                    .full_name
                }}
              </div>

              <Button
                variant="ghost"
                class="m-1 !size-4 rounded-full"
                @click.stop="
                  removeValue(
                    assignee.name
                  )
                "
              >
                <template #icon>
                  <span
                    class="lucide-x h-3 w-3 text-ink-gray-6"
                    aria-hidden="true"
                  />
                </template>
              </Button>
            </div>
          </Tooltip>
        </div>
      </template>

      <template #item-prefix="{ option }">
        <UserAvatar
          class="mr-2"
          :user="option.value"
          size="sm"
        />
      </template>

      <template #item-label="{ option }">
        <Tooltip :text="option.value">
          <div
            class="cursor-pointer text-ink-gray-9"
          >
            {{
              getUser(option.value)
                .full_name
            }}
          </div>
        </Tooltip>
      </template>
    </Link>

    <div
      class="flex items-center justify-between gap-2"
    >
      <div
        class="cursor-pointer select-none text-base text-ink-gray-5"
        @click="
          assignToMe =
            !assignToMe
        "
      >
        {{ __('Assign To Me') }}
      </div>

      <Switch
        v-model="assignToMe"
        @click.stop
      />
    </div>
  </div>
</template>

<script setup>
import UserAvatar from '@/components/UserAvatar.vue'
import Link from '@/components/Controls/Link.vue'

import {
  usersStore,
} from '@/stores/users'

import {
  Tooltip,
  Switch,
  createResource,
} from 'frappe-ui'

import {
  useTelemetry,
} from 'frappe-ui/frappe'

import {
  computed,
  ref,
  watch,
} from 'vue'

const props = defineProps({
  doctype: {
    type: String,
    default: '',
  },

  docname: {
    type: String,
    default: '',
  },

  open: {
    type: Boolean,
    default: false,
  },

  onUpdate: {
    type: Function,
    default: null,
  },
})

const {
  capture,
} = useTelemetry()

const assignees = defineModel({
  type: Array,
  default: () => [],
})

const oldAssignees = ref([])
const assignToMe = ref(false)

const error = ref('')

const {
  users,
  getUser,
} = usersStore()

/*
 * CRM users được ưu tiên.
 *
 * Nếu crmUsers đang rỗng hoặc chưa được cấu hình,
 * fallback sang allUsers để Assign To không bị
 * "No results found".
 */
const eligibleUserNames =
  computed(() => {
    const crmUsers =
      users.data?.crmUsers ||
      []

    const allUsers =
      users.data?.allUsers ||
      []

    const source =
      crmUsers.length
        ? crmUsers
        : allUsers

    return source
      .map(
        (user) =>
          user.name
      )
      .filter(
        (name) =>
          name &&
          name !== 'Guest'
      )
  })

const removeValue = (
  value
) => {
  if (
    value ===
    getUser('').name
  ) {
    assignToMe.value =
      false
  }

  assignees.value =
    assignees.value.filter(
      (assignee) =>
        assignee.name !==
        value
    )
}

const addValue = (
  value
) => {
  if (!value) {
    return false
  }

  if (
    value ===
    getUser('').name
  ) {
    assignToMe.value =
      true
  }

  error.value = ''

  const obj = {
    name: value,

    image:
      getUser(value)
        .user_image,

    label:
      getUser(value)
        .full_name,
  }

  if (
    !assignees.value.find(
      (assignee) =>
        assignee.name ===
        value
    )
  ) {
    assignees.value.push(
      obj
    )
  }

  return true
}

watch(
  assignToMe,
  (val) => {
    const user =
      getUser('')

    if (val) {
      addValue(
        user.name
      )
    } else {
      removeValue(
        user.name
      )
    }
  }
)

watch(
  () => props.open,

  (val) => {
    if (val) {
      oldAssignees.value = [
        ...(
          assignees.value ||
          []
        ),
      ]

      assignToMe.value =
        assignees.value.some(
          (assignee) =>
            assignee.name ===
            getUser('').name
        )
    } else {
      updateAssignees()
    }
  },

  {
    immediate: true,
  }
)

async function updateAssignees() {
  if (
    JSON.stringify(
      oldAssignees.value
    ) ===
    JSON.stringify(
      assignees.value
    )
  ) {
    return
  }

  const removedAssignees =
    oldAssignees.value
      .filter(
        (assignee) =>
          !assignees.value.find(
            (a) =>
              a.name ===
              assignee.name
          )
      )
      .map(
        (assignee) =>
          assignee.name
      )

  const addedAssignees =
    assignees.value
      .filter(
        (assignee) =>
          !oldAssignees.value.find(
            (a) =>
              a.name ===
              assignee.name
          )
      )
      .map(
        (assignee) =>
          assignee.name
      )

  if (props.onUpdate) {
    props.onUpdate(
      addedAssignees,
      removedAssignees,
      addAssignees,
      removeAssignees
    )

    return
  }

  if (
    removedAssignees.length
  ) {
    await removeAssignees.submit(
      removedAssignees
    )
  }

  if (
    addedAssignees.length
  ) {
    await addAssignees.submit(
      addedAssignees
    )
  }
}

const addAssignees =
  createResource({
    url:
      'frappe.desk.form.assign_to.add',

    makeParams:
      (
        addedAssignees
      ) => ({
        doctype:
          props.doctype,

        name:
          props.docname,

        assign_to:
          addedAssignees,
      }),

    onSuccess: () => {
      capture(
        'assign_to',
        {
          doctype:
            props.doctype,
        }
      )
    },
  })

const removeAssignees =
  createResource({
    url:
      'crm.api.doc.remove_assignments',

    makeParams:
      (
        removedAssignees
      ) => ({
        doctype:
          props.doctype,

        name:
          props.docname,

        assignees:
          removedAssignees,
      }),
  })
</script>